package it.polito.wa2.catalogue.adapters.outbound.http.inventory

import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.service.annotation.HttpExchange
import org.springframework.web.service.annotation.PutExchange
import java.time.Instant

/**
 * Declarative client of the Inventory & Orders internal API, mirroring its OpenAPI contract.
 * The implementation is generated by Spring from these annotations.
 */
@HttpExchange(contentType = "application/json")
interface InventoryOrdersApi {

    /** `PUT /internal/sessions/{sessionId}/inventory`: 201 on first provisioning, 200 on an identical retry. */
    @PutExchange("/internal/sessions/{sessionId}/inventory")
    fun provisionSessionInventory(
        @PathVariable sessionId: String,
        @RequestBody request: ProvisionInventoryRequest
    ): ResponseEntity<Void>
}

/** Request body of `PUT /internal/sessions/{sessionId}/inventory`. */
data class ProvisionInventoryRequest(
    val configurationVersion: Long,
    val eventId: String,
    val organiserId: String,
    val venueId: String,
    val planId: String,
    val salesOpenAt: Instant,
    val salesCloseAt: Instant,
    val startsAt: Instant,
    val seats: List<InventorySeatRequest>
)

/** A seat with its location, price tier and unit price, as expected by Inventory & Orders. */
data class InventorySeatRequest(
    val seatId: String,
    val sector: String,
    val row: String,
    val number: String,
    val priceTierId: String,
    val unitPrice: MoneyRequest
)

/** EUR amount as a decimal string with two fractional digits. */
data class MoneyRequest(
    val amount: String,
    val currency: String
)
